tool_input_args.value:
node -e "
const sqlite3 = require('better-sqlite3');
" 2>&1 || echo "---"; node -e "const Database = require('sql.js'); console.log('sql.js available');" 2>&1 || echo "no sql.js"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 5').all();
  console.log('\nTable:', t.name);
  if (rows.length > 0) console.log('Columns:', Object.keys(rows[0]));
  rows.forEach(r => console.log(r));
}
db.close();
"

